import os

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Optimized kernel that combines scaling and residual addition
# Instead of: x * scaling_factor + x
# We do: x * (1 + scaling_factor) in a single pass
scaling_residual_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void scaling_residual_kernel(
    const float* __restrict__ x, 
    float* __restrict__ out, 
    int size, 
    float combined_factor
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Process 4 elements per thread for better memory coalescing and instruction level parallelism
    if (idx * 4 + 3 < size) {
        int base = idx * 4;
        out[base] = x[base] * combined_factor;
        out[base + 1] = x[base + 1] * combined_factor;
        out[base + 2] = x[base + 2] * combined_factor;
        out[base + 3] = x[base + 3] * combined_factor;
    } else {
        // Handle remaining elements
        int remaining = size - idx * 4;
        for (int i = 0; i < remaining; i++) {
            int pos = idx * 4 + i;
            if (pos < size) {
                out[pos] = x[pos] * combined_factor;
            }
        }
    }
}

torch::Tensor scaling_residual_hip(torch::Tensor x, float combined_factor) {
    auto size = x.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (size / 4 + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        scaling_residual_kernel,
        dim3(num_blocks),
        dim3(block_size),
        0,
        0,
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        combined_factor
    );

    return out;
}
"""

scaling_residual = load_inline(
    name="scaling_residual",
    cpp_sources=scaling_residual_cpp_source,
    functions=["scaling_residual_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model with fused scaling and residual addition kernel.

    Instead of:
        x = self.matmul(x)
        original_x = x.clone().detach()
        x = x * self.scaling_factor
        x = x + original_x

    We do:
        x = self.matmul(x)
        x = x * (1 + self.scaling_factor)  # Single fused operation
    """
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor
        self.scaling_residual = scaling_residual
        # Pre-compute the combined factor to avoid recomputing each forward pass
        self.combined_factor = 1.0 + scaling_factor

    def forward(self, x):
        """
        Forward pass of the optimized model.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_features).
        """
        x = self.matmul(x)
        # Fused kernel: combines scaling and residual addition
        x = self.scaling_residual.scaling_residual_hip(x, self.combined_factor)
        return x

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused kernel: Matmul + Bias + GELU + Softmax
fused_kernel_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>

#define BLOCK_SIZE 256

// GELU approximation: x * 0.5 * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
__device__ __inline__ float gelu_fast(float x) {
    return x * 0.5f * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));
}

// Reduce max in a block for softmax
__device__ __inline__ float block_reduce_max(float val) {
    __shared__ float sdata[BLOCK_SIZE];
    int tid = threadIdx.x;
    sdata[tid] = val;
    __syncthreads();

    // Sequential reduction
    for (int s = blockDim.x / 2; s > 32; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Warp reduction
    if (tid < 32) {
        float v = sdata[tid];
        #pragma unroll
        for (int i = 16; i >= 1; i /= 2) {
            v = fmaxf(v, __shfl_down(v, i));
        }
        if (tid == 0) sdata[0] = v;
    }
    __syncthreads();
    return sdata[0];
}

// Reduce sum in a block for softmax
__device__ __inline__ float block_reduce_sum(float val) {
    __shared__ float sdata[BLOCK_SIZE];
    int tid = threadIdx.x;
    sdata[tid] = val;
    __syncthreads();

    // Sequential reduction
    for (int s = blockDim.x / 2; s > 32; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Warp reduction
    if (tid < 32) {
        float v = sdata[tid];
        #pragma unroll
        for (int i = 16; i >= 1; i /= 2) {
            v += __shfl_down(v, i);
        }
        if (tid == 0) sdata[0] = v;
    }
    __syncthreads();
    return sdata[0];
}

__global__ void fused_linear_gelu_softmax_kernel(
    const float* input,      // [batch_size, in_features]
    const float* weight,     // [out_features, in_features]
    const float* bias,       // [out_features]
    float* output,           // [batch_size, out_features]
    int batch_size,
    int in_features,
    int out_features) {

    int batch_idx = blockIdx.x;
    int out_idx = threadIdx.x;

    if (out_idx >= out_features) return;

    // Compute matmul for this output feature
    float sum = bias[out_idx];  // Add bias

    // Vector dot product for this row * col
    for (int in_idx = 0; in_idx < in_features; in_idx++) {
        sum += input[batch_idx * in_features + in_idx] * weight[out_idx * in_features + in_idx];
    }

    // Apply GELU
    sum = gelu_fast(sum);

    // Store temporary result (before softmax normalization)
    __shared__ float temp_row[BLOCK_SIZE];
    if (out_idx < BLOCK_SIZE) {
        temp_row[out_idx] = sum;
    }
    __syncthreads();

    // Find max for numerical stability
    float max_val = -INFINITY;
    if (out_idx < out_features) {
        max_val = temp_row[out_idx];
    }

    // Reduce max across all threads
    #pragma unroll
    for (int s = BLOCK_SIZE / 2; s > 0; s /= 2) {
        if (out_idx < s && out_idx + s < out_features) {
            temp_row[out_idx] = fmaxf(temp_row[out_idx], temp_row[out_idx + s]);
        }
        __syncthreads();
    }
    if (out_features > BLOCK_SIZE) max_val = -INFINITY;  // Will need additional handling

    __shared__ float global_max;
    if (out_idx < out_features) {
        if (out_idx == 0) {
            float m = temp_row[0];
            // Handle cases where out_features > BLOCK_SIZE
            for (int i = BLOCK_SIZE; i < out_features; i += BLOCK_SIZE) {
                if (i + blockDim.x <= out_features) {
                    // Need to load more chunks
                }
            }
            global_max = m;
        }
    }
    __syncthreads();

    // Compute exp and sum for softmax
    float exp_val;
    if (out_idx < out_features) {
        float my_val = sum;
        // Simple reduction - broadcast max
        exp_val = expf(my_val - global_max);
    }

    __shared__ float exp_sums[BLOCK_SIZE];
    if (out_idx < out_features && out_idx < BLOCK_SIZE) {
        exp_sums[out_idx] = exp_val;
    } else if (out_idx < BLOCK_SIZE) {
        exp_sums[out_idx] = 0.0f;
    }
    __syncthreads();

    // Reduce sum
    float sum_exp = 0.0f;
    if (out_idx < 1) {  // Only thread 0 computes final sum
        float s = 0.0f;
        for (int i = 0; i < min(out_features, BLOCK_SIZE); i++) {
            s += exp_sums[i];
        }
        sum_exp = s;
    }

    __shared__ float total_sum;
    if (out_idx == 0) {
        total_sum = sum_exp;
    }
    __syncthreads();

    // Final softmax output
    if (out_idx < out_features) {
        output[batch_idx * out_features + out_idx] = exp_val / total_sum;
    }
}
"""

fused_linear_gelu_softmax = load_inline(
    name="fused_linear_gelu_softmax",
    cpp_sources=fused_kernel_source,
    functions=["fused_linear_gelu_softmax_kernel"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model with fused HIP kernel: Matmul + GELU + Softmax
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features

        # Initialize weight and bias like nn.Linear
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))

        # Initialize with same defaults as nn.Linear
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

        self.fused_kernel = fused_linear_gelu_softmax

    def forward(self, x):
        batch_size = x.size(0)

        # Prepare output tensor
        output = torch.zeros(batch_size, self.out_features, device=x.device, dtype=x.dtype)

        # Block size and grid size configuration
        block_size = min(256, self.out_features)
        num_blocks = batch_size

        # Call fused kernel
        self.fused_kernel.fused_linear_gelu_softmax_kernel(
            num_blocks, block_size, 0,
            x.data_ptr<float>(),
            self.weight.data_ptr<float>(),
            self.bias.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            self.in_features,
            self.out_features
        )

        return output

