#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_subtract_tanh_subtract_avgpool_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int height,
    int width,
    float subtract1_value,
    float subtract2_value,
    int pool_size) {

    // Output dimensions
    int out_h = height / pool_size;
    int out_w = width / pool_size;

    int batch = blockIdx.z;
    int channel = blockIdx.y;
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    int out_y = blockIdx.y * blockDim.y + threadIdx.y;  // This is wrong, need to fix indexing

    // Correct indexing
    int out_h_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int out_w_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch >= batch_size || out_h_idx >= out_h || out_w_idx >= out_w) {
        return;
    }

    // For average pooling, compute average over pool_size x pool_size window
    float sum = 0.0f;
    int count = 0;

    int base_h = out_h_idx * pool_size;
    int base_w = out_w_idx * pool_size;

    for (int ph = 0; ph < pool_size; ph++) {
        for (int pw = 0; pw < pool_size; pw++) {
            int h = base_h + ph;
            int w = base_w + pw;

            if (h < height && w < width) {
                int idx = batch * channels * height * width + channel * height * width + h * width + w;
                float val = input[idx];
                val = tanhf(val - subtract1_value);
                val = val - subtract2_value;
                sum += val;
                count++;
            }
        }
    }

    int out_idx = batch * channels * out_h * out_w + channel * out_h * out_w + out_h_idx * out_w + out_w_idx;
    output[out_idx] = sum / count;
}
"""

# Better version with proper indexing
fused_kernel_cpp_source_v2 = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_subtract_tanh_subtract_avgpool_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int height,
    int width,
    float subtract1_value,
    float subtract2_value,
    int pool_size) {

    // Output dimensions after pooling
    int out_h = height / pool_size;
    int out_w = width / pool_size;

    // Use 3D grid: x->width, y->height, z->batch
    // Combined with channels in y-dim
    int out_col = blockIdx.x * blockDim.x + threadIdx.x;

    // Calculate row and channel from y dimension
    int combined_y = blockIdx.y * blockDim.y + threadIdx.y;
    int out_row = combined_y % out_h;
    int batch = combined_y / (out_h * channels);
    int channel = (combined_y / out_h) % channels;

    // Use z dimension for remaining batches
    batch += blockIdx.z;

    if (batch >= batch_size || out_row >= out_h || out_col >= out_w) {
        return;
    }

    // For average pooling, compute average over pool_size x pool_size window
    float sum = 0.0f;
    int count = 0;

    int base_row = out_row * pool_size;
    int base_col = out_col * pool_size;

    for (int ph = 0; ph < pool_size; ph++) {
        for (int pw = 0; pw < pool_size; pw++) {
            int h = base_row + ph;
            int w = base_col + pw;

            if (h < height && w < width) {
                int idx = ((batch * channels + channel) * height + h) * width + w;
                float val = input[idx];
                // Apply fused operations: subtract -> tanh -> subtract
                val = tanhf(val - subtract1_value);
                val = val - subtract2_value;
                sum += val;
                count++;
            }
        }
    }

    int out_idx = ((batch * channels + channel) * out_h + out_row) * out_w + out_col;
    output[out_idx] = sum / count;
}

torch::Tensor fused_subtract_tanh_subtract_avgpool(
    torch::Tensor input,
    float subtract1_value,
    float subtract2_value,
    int pool_size) {

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    int out_h = height / pool_size;
    int out_w = width / pool_size;

    auto output = torch::zeros({batch_size, channels, out_h, out_w}, input.options());

    const int block_size = 16;
    dim3 block(block_size, block_size);

    // Grid: x for columns (out_w), y for rows and channels combined, z for remaining batches
    // We need to fit all batches, channels, out_h, out_w into grid dimensions
    int grid_x = (out_w + block_size - 1) / block_size;
    int grid_y = (batch_size * channels * out_h + block_size - 1) / block_size;
    dim3 grid(grid_x, grid_y);

    fused_subtract_tanh_subtract_avgpool_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        subtract1_value,
        subtract2_value,
        pool_size);

    return output;
}
"""

fused_ops = load_inline(
