matmul_swish_scale_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE_M 32
#define TILE_SIZE_N 32
#define TILE_SIZE_K 8
#define BLOCK_SIZE 256

__device__ __forceinline__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-fmaxf(-50.0f, fminf(50.0f, x))));
}

__device__ __forceinline__ float swish(float x) {
    return x * sigmoid(x);
}

__global__ void matmul_swish_scale_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int M,
    int N,
    int K,
    float scaling_factor) {

    // Each thread computes one output element
    int tx = threadIdx.x;
    int m = blockIdx.x * blockDim.x + tx;

    // Each block processes a column of weight matrix (N dimension)
    int n_base = blockIdx.y * TILE_SIZE_N;

    __shared__ float weight_shmem[TILE_SIZE_N * TILE_SIZE_K];

    if (m < M) {
        float sum = 0.0f;

        // Iterate over K dimension
        for (int k_start = 0; k_start < K; k_start += TILE_SIZE_K) {
            // Load weights into shared memory
            #pragma unroll
            for (int i = 0; i < TILE_SIZE_N; ++i) {
                int n = n_base + i;
                #pragma unroll
                for (int j = 0; j < TILE_SIZE_K; ++j) {
                    if (n < N && (k_start + j) < K) {
                        weight_shmem[i * TILE_SIZE_K + j] = weight[n * K + (k_start + j)];
                    } else {
                        weight_shmem[i * TILE_SIZE_K + j] = 0.0f;
                    }
                }
            }

            __syncthreads();

            // Compute partial sum
            if (n_base < N) {
                #pragma unroll
                for (int j = 0; j < TILE_SIZE_K; ++j) {
                    int k = k_start + j;
                    if (k < K) {
                        float in_val = input[m * K + k];
                        #pragma unroll
                        for (int i = 0; i < TILE_SIZE_N; ++i) {
                            int n = n_base + i;
                            if (n < N) {
                                sum += in_val * weight_shmem[i * TILE_SIZE_K + j];
                            }
                        }
                    }
                }
            }

            __syncthreads();
        }

        // Apply Swish and Scaling, write output
        for (int i = 0; i < TILE_SIZE_N; ++i) {
            int n = n_base + i;
            if (n < N) {
                float val = sum;
                val = swish(val);
                val = val * scaling_factor;
                output[m * N + n] = val;
            }
        }
    }
}

torch::Tensor matmul_swish_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    float scaling_factor) {

    int M = input.size(0);  // batch_size
    int K = input.size(1);
    int N = weight.size(0);

    auto output = torch::zeros({M, N}, input.options());

    const int block_size = BLOCK_SIZE;

    // Grid for M dimension
    dim3 block(block_size);
    dim3 grid((M + block_size - 1) / block_size, (N + TILE_SIZE_N - 1) / TILE_SIZE_N);

    matmul_swish_scale_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        M, N, K,
        scaling_factor);

    return output;
}
"""

