conv_instnorm_divide_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

// Fused kernel: Conv2d + InstanceNorm2d + Element-wise division
__global__ void conv_instnorm_divide_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int kernel_size,
    int padding,
    float divide_by,
    float eps) {

    // Block and thread indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z; // batch index

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Shared memory for mean and variance
    extern __shared__ float shared[];
    float* s_mean = shared;
    float* s_var = shared + out_channels;

    // Output pixel position
    int x = bx * blockDim.x + tx;
    int y = by * blockDim.y + ty;

    // Initialize mean and variance accumulators for this thread block
    for (int oc = threadIdx.y * blockDim.x + threadIdx.x; oc < out_channels; oc += blockDim.y * blockDim.x) {
        s_mean[oc] = 0.0f;
        s_var[oc] = 0.0f;
    }
    __syncthreads();

    // Process each output channel
    int oc_start = bz * out_channels; // Only use bz as batch index

    for (int out_c = 0; out_c < out_channels; out_c++) {
        if (x < width && y < height) {
            // Compute convolution
            float sum = 0.0f;

            if (bias != nullptr) {
                sum = bias[out_c];
            }

            // Loop over input channels and kernel
            for (int in_c = 0; in_c < in_channels; in_c++) {
                for (int ky = 0; ky < kernel_size; ky++) {
                    for (int kx = 0; kx < kernel_size; kx++) {
                        int in_y = y + ky - padding;
                        int in_x = x + kx - padding;

                        if (in_y >= 0 && in_y < height && in_x >= 0 && in_x < width) {
                            int in_idx = ((bz * in_channels + in_c) * height + in_y) * width + in_x;
                            int weight_idx = (out_c * in_channels + in_c) * kernel_size * kernel_size + ky * kernel_size + kx;
                            sum += input[in_idx] * weight[weight_idx];
                        }
                    }
                }
            }

            // Store to shared memory for mean/variance computation
            int pixel_idx = threadIdx.y * blockDim.x + threadIdx.x;
            int buffer_start = 2 * out_channels;
            if (pixel_idx < height * width) {
                shared[buffer_start + out_c * height * width + y * width + x] = sum;
            }
        }
    }
    __syncthreads();

    // Compute channel-wise statistics using reduction
    for (int out_c = 0; out_c < out_channels; out_c++) {
        float local_sum = 0.0f;
        float local_sq_sum = 0.0f;
        int count = 0;

        for (int i = threadIdx.y * blockDim.x + threadIdx.x; i < height * width; i += blockDim.y * blockDim.x) {
            float val = shared[2 * out_channels + out_c * height * width + i];
            if (x < width && y < height) {
                int py = i / width;
                int px = i % width;
                if (py == y && px == x) {
                    local_sum += val;
                    local_sq_sum += val * val;
                    count++;
                }
            }
        }

        // Atomic add to shared memory
        atomicAdd(&s_mean[out_c], local_sum);
        atomicAdd(&s_var[out_c], local_sq_sum);
    }
    __syncthreads();

    // Compute final mean and variance
    int num_pixels = height * width;
    for (int out_c = 0; out_c < out_channels; out_c++) {
        s_mean[out_c] /= num_pixels;
        s_var[out_c] = fmaxf(s_var[out_c] / num_pixels - s_mean[out_c] * s_mean[out_c], 0.0f);
    }
    __syncthreads();

    // Normalize and output
    for (int out_c = 0; out_c < out_channels; out_c++) {
        if (x < width && y < height) {
            int pixel_idx = threadIdx.y * blockDim.x + threadIdx.x;
            if (pixel_idx < height * width) {
                float val = shared[2 * out_channels + out_c * height * width + y * width + x];
                float mean = s_mean[out_c];
                float var = s_var[out_c];
                float std = sqrtf(var + eps);
                float norm_val = (val - mean) / std;
                norm_val = norm_val / divide_by;

                int out_idx = ((bz * out_channels + out_c) * height + y) * width + x;
                output[out_idx] = norm_val;
            }
        }
    }
}

torch::Tensor conv_instnorm_divide_hip(
    torch::Tensor input,
