#include <hip/hip_runtime.h>

__global__ void fused_swish_bias_groupnorm_kernel(
    const float* x,
    const float* weight,
    const float* bias_gn,
    const float* bias_add,
    float* out,
    int batch_size,
    int num_features,
    int num_groups,
    float eps
) {
    int batch_idx = blockIdx.x;
    int thread_idx = threadIdx.x;
    int threads_per_block = blockDim.x;

    int features_per_group = num_features / num_groups;

    // Each thread handles one element in a group
    // All threads in a block process all elements of one batch sample

    extern __shared__ float shared_data[];
    float* s_sum = shared_data;
    float* s_sq_sum = &shared_data[num_groups];

    // Initialize shared memory
    if (thread_idx < num_groups) {
        s_sum[thread_idx] = 0.0f;
        s_sq_sum[thread_idx] = 0.0f;
    }
    __syncthreads();

    // Each thread processes elements across all groups
    // Use thread_idx to iterate over features
    for (int g = 0; g < num_groups; g++) {
        int feature_idx = g * features_per_group + (thread_idx % features_per_group);
        if (feature_idx < num_features && (thread_idx / features_per_group) < features_per_group) {
            int idx = batch_idx * num_features + feature_idx;
            float val = x[idx];

            // Apply swish first: sigmoid(x) * x
            float sigmoid_val = 1.0f / (1.0f + expf(-val));
            val = sigmoid_val * val;

            // Store for later
            // Compute partial sums for this thread's elements
        }
    }

    // Reduction across threads: each thread handles a subset of features
    for (int g = 0; g < num_groups; g++) {
        float local_sum = 0.0f;
        float local_sq_sum = 0.0f;

        for (int f = 0; f < features_per_group; f++) {
            int feature_idx = g * features_per_group + f;
            int thread_for_feature = f;  // Simple mapping

            if (thread_idx == thread_for_feature) {
                int idx = batch_idx * num_features + feature_idx;
                float val = x[idx];

                // Swish
                float sigmoid_val = 1.0f / (1.0f + expf(-val));
                val = sigmoid_val * val;

                local_sum = val;
                local_sq_sum = val * val;
            }
        }

        // Atomic add to group sums
        atomicAdd(&s_sum[g], local_sum);
        atomicAdd(&s_sq_sum[g], local_sq_sum);
    }

    __syncthreads();

    // Compute mean and variance for each group
    float mean[num_groups];
    float variance[num_groups];

    for (int g = 0; g < num_groups; g++) {
        mean[g] = s_sum[g] / features_per_group;
        variance[g] = s_sq_sum[g] / features_per_group - mean[g] * mean[g];
    }

    // Normalize and apply bias + swish
    for (int g = 0; g < num_groups; g++) {
        for (int f = 0; f < features_per_group; f++) {
            int feature_idx = g * features_per_group + f;
            int idx = batch_idx * num_features + feature_idx;

            if (f == thread_idx) {
                int idx_x = batch_idx * num_features + feature_idx;
                float val = x[idx_x];

                // Swish
                float sigmoid_val = 1.0f / (1.0f + expf(-val));
                val = sigmoid_val * val;

                // GroupNorm: normalize
                float std = sqrtf(variance[g] + eps);
                val = (val - mean[g]) / std;

                // Apply weight and bias
                if (weight != nullptr) {
                    val = val * weight[feature_idx];
                }
                if (bias_gn != nullptr) {
                    val = val + bias_gn[feature_idx];
                }

                // Add bias term
                if (bias_add != nullptr) {
                    val = val + bias_add[feature_idx];
                }

                out[idx] = val;
            }
        }
    }
}

