    }

    __syncthreads();

    // Normalize, apply bias, and output
    for (int elem = thread_idx; elem < total_elements; elem += total_threads) {
        int group_idx = elem / features_per_group;
        int idx = batch_idx * num_features + elem;

        float val = x[idx];

        // Swish
        float sigmoid_val = 1.0f / (1.0f + expf(-val));
        val = sigmoid_val * val;

        // GroupNorm
        float mean = group_mean[group_idx];
        float var = group_var[group_idx];
