class ModelNew(nn.Module):
    """
    Optimized model with custom HIP kernels for:
    - Matmul using tiling
    - AvgPool (using PyTorch)
    - Fused GELU + Scale
    - Parallel Max reduction
    """
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.pool_kernel_size = pool_kernel_size
        self.scale_factor = scale_factor
        self.avg_pool = nn.AvgPool1d(kernel_size=pool_kernel_size)

        # Initialize weight (transposed for row-major computation)
        self.register_buffer('weight', torch.randn(out_features, in_features))

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size,).
        """
        batch_size = x.size(0)

        # Custom matmul: x @ weight.T
        x = matmul_module.matmul_hip(x.view(-1, self.in_features), self.weight.T, self.out_features)

        # Restore batch dimension (result is [batch_size, out_features])
        x = x.view(batch_size, self.out_features)

        # AvgPool (keeping PyTorch implementation - already efficient)
        x = self.avg_pool(x.unsqueeze(1)).squeeze(1)

        # Fused GELU + Scale
        x = gelu_scale_module.gelu_scale_hip(x, self.scale_factor)

        # Custom max reduction
        x = max_reduce_module.max_reduce_hip(x)

        return x

