matmul_divide_gelu_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 16
#define BLOCK_ROWS 8
#define BLOCK_COLS 16

__global__ void matmul_divide_gelu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int input_size,
    int output_size,
    float divisor
) {
    __shared__ float input_tile[BLOCK_ROWS][TILE_SIZE];
    __shared__ float weight_tile[TILE_SIZE][BLOCK_COLS];

    int batch = blockIdx.x * BLOCK_ROWS + threadIdx.y;
    int out_col = blockIdx.y * BLOCK_COLS + threadIdx.x;

    // Check bounds
    if (batch >= batch_size || out_col >= output_size) {
        return;
    }

    float sum = 0.0f;

    int num_tiles = (input_size + TILE_SIZE - 1) / TILE_SIZE;

    for (int tile = 0; tile < num_tiles; tile++) {
        // Load input tile
        int in_col = tile * TILE_SIZE + threadIdx.x;
        if (threadIdx.y < BLOCK_ROWS && in_col < input_size) {
            int input_idx = batch * input_size + in_col;
            if (batch < batch_size) {
                input_tile[threadIdx.y][threadIdx.x] = __ldg(&input[input_idx]);
            } else {
                input_tile[threadIdx.y][threadIdx.x] = 0.0f;
            }
        } else {
            input_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load weight tile
        int weight_row = tile * TILE_SIZE + threadIdx.y;
        if (weight_row < input_size && threadIdx.x < BLOCK_COLS) {
            int weight_idx = weight_row * output_size + out_col;
            if (in_col < input_size) {
                weight_tile[threadIdx.y][threadIdx.x] = __ldg(&weight[weight_idx]);
            } else {
                weight_tile[threadIdx.y][threadIdx.x] = 0.0f;
            }
        } else {
            weight_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += input_tile[threadIdx.y][k] * weight_tile[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Divide by divisor
    sum = sum / divisor;

    // Apply GELU activation
    // gelu(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    float x = sum;
    float x_cube = x * x * x;
    float tanh_arg = 0.7978845608028654f * (x + 0.044715f * x_cube);
    float gelu_val = 0.5f * x * (1.0f + tanhf(tanh_arg));

    // Write result
    int output_idx = batch * output_size + out_col;
    if (batch < batch_size && out_col < output_size) {
        output[output_idx] = gelu_val;
    }
}

torch::Tensor matmul_divide_gelu_hip(torch::Tensor input, torch::Tensor weight, float divisor) {
    int batch_size = input.size(0);
    int input_size = input.size(1);
    int output_size = weight.size(1);

    auto output = torch::zeros({batch_size, output_size}, input.options());

    const int block_rows = 8;
    const int block_cols = 16;

    dim3 block(BLOCK_COLS, block_rows);
    dim3 grid((batch_size + block_rows - 1) / block_rows, 
              (output_size + block_cols - 1) / block_cols);

    matmul_divide_gelu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        input_size,
        output_size,
        divisor
    );

    return output;
}
