// GELU approximation: x * 0.5 * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
__device__ __inline__ float gelu_fast(float x) {
    return x * 0.5f * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));
}

__global__ void fused_linear_gelu_softmax_kernel(
    const float* input,      // [batch_size, in_features]
    const float* weight,     // [out_features, in_features]
    const float* bias,       // [out_features]
    float* output,           // [batch_size, out_features]
    int batch_size,
    int in_features,
    int out_features) {

    int batch_idx = blockIdx.x;
    int out_idx = threadIdx.x;

    if (out_idx >= out_features) return;

    // Each thread computes one output element
    int global_idx = batch_idx * out_features + out_idx;

    // Compute matmul for this output feature
    float sum = bias[out_idx];  // Add bias

    // Vector dot product: sum over in_features
    for (int in_idx = 0; in_idx < in_features; in_idx++) {
        sum += input[batch_idx * in_features + in_idx] * weight[out_idx * in_features + in_idx];
    }

    // Apply GELU activation
    float gelu_val = sum * 0.5f * (1.0f + tanhf(0.7978845608028654f * (sum + 0.044715f * sum * sum * sum)));

    __shared__ float shared_data[256];

    // First pass: find max for numerical stability
    int tid = out_idx;
    shared_data[tid] = gelu_val;
    __syncthreads();

    // Parallel reduction for max
    for (int s = 128; s > 0; s >>= 1) {
        if (tid < s && (tid + s) < out_features) {
            shared_data[tid] = fmaxf(shared_data[tid], shared_data[tid + s]);
        }
        __syncthreads();
    }

    float max_val = shared_data[0];
    __syncthreads();

    // Second pass: compute exp and sum
    float exp_val = expf(gelu_val - max_val);

    shared_data[tid] = (tid < out_features) ? exp_val : 0.0f;
    __syncthreads();

    // Parallel reduction for sum
    for (int s = 128; s > 0; s >>= 1) {
        if (tid < s && (tid + s) < out_features) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    float sum_exp = shared_data[0];

    // Output normalized softmax value
    if (tid < out_features) {
        output[global_idx] = exp_val / sum_exp;
    }
}
"""

