conv_instnorm_divide_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void conv_instnorm_divide_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int kernel_size,
    int padding,
    float divide_by,
    float eps) {

    // Output pixel position
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int batch_idx = blockIdx.z;

    // Shared memory for channel statistics (mean and variance)
    extern __shared__ float shared_mem[];
    float* s_mean = shared_mem;
    float* s_var = shared_mem + out_channels;

    // Each thread computes one output pixel and one channel
    for (int out_c = 0; out_c < out_channels; out_c++) {
        int tid = threadIdx.y * blockDim.x + threadIdx.x;

        // Compute convolution output
        float conv_out = 0.0f;

        if (bias != nullptr) {
            conv_out = bias[out_c];
        }

        // Convolution computation
        for (int in_c = 0; in_c < in_channels; in_c++) {
            for (int ky = 0; ky < kernel_size; ky++) {
                for (int kx = 0; kx < kernel_size; kx++) {
                    int in_y = y + ky - padding;
                    int in_x = x + kx - padding;

                    if (in_y >= 0 && in_y < height && in_x >= 0 && in_x < width) {
                        int in_idx = ((batch_idx * in_channels + in_c) * height + in_y) * width + in_x;
                        int w_idx = ((out_c * in_channels + in_c) * kernel_size + ky) * kernel_size + kx;
                        conv_out += input[in_idx] * weight[w_idx];
                    }
                }
            }
        }

        // Store intermediate value in shared memory for channel statistics
        int pixel_linear_idx = y * width + x;

        // First pass: initialize local accumulators
        float local_sum = 0.0f;
        float local_sq_sum = 0.0f;

        if (x < width && y < height) {
            // Shared memory buffer for this channel's values
            float* channel_buffer = shared_mem + 2 * out_channels;
            channel_buffer[out_c * (height * width) + pixel_linear_idx] = conv_out;
            local_sum = conv_out;
            local_sq_sum = conv_out * conv_out;
        }
        __syncthreads();

        // Reduce across threads to compute mean and variance
        atomicAdd(&s_mean[out_c], local_sum);
        atomicAdd(&s_var[out_c], local_sq_sum);
        __syncthreads();

        // Compute final mean and variance
        int num_pixels = height * width;
        if (tid == 0) {
            s_mean[out_c] = s_mean[out_c] / num_pixels;
            float variance = s_var[out_c] / num_pixels - s_mean[out_c] * s_mean[out_c];
            s_var[out_c] = fmaxf(variance, 0.0f);
        }
        __syncthreads();

        // Normalize and output
        if (x < width && y < height) {
            float mean = s_mean[out_c];
            float variance = s_var[out_c];
            float std = sqrtf(variance + eps);
            float norm_val = (conv_out - mean) / std;
            norm_val = norm_val / divide_by;

            int out_idx = ((batch_idx * out_channels + out_c) * height + y) * width + x;
            output[out_idx] = norm_val;
        }

        // Reset shared memory for next channel
        if (tid == 0) {
            s_mean[out_c] = 0.0f;
            s_var[out_c] = 0.0f;
        }
        __syncthreads();
    }
}

torch::Tensor conv_instnorm_divide_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float divide_by) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);
    int padding = kernel_size / 2;
    float eps = 1e-5f;

    auto output = torch::zeros({batch_size, out_channels, height, width}, input.options());

    const int threads_x = 16;
    const int threads_y = 16;
    int num_blocks_x = (width + threads_x - 1) / threads_x;
    int num_blocks_y = (height + threads_y - 1) / threads_y;

    // Shared memory: [mean[out_channels], var[out_channels], channel_buffer[out_channels * height * width]]
    int shared_mem_size = (2 * out_channels + out_channels * height * width) * sizeof(float);

    dim3 blocks(num_blocks_x, num_blocks_y, batch_size);
    dim3 threads(threads_x, threads_y);

    conv_instnorm_divide_kernel<<<blocks, threads, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        height,
        width,
        kernel_size,
        padding,
        divide_by,
        eps);

    return output;
}
"""

