os.environ["CXX"] = "hipcc"

# Fused kernel: linear (matmul+bias) + dropout + softmax
# Optimizations:
# 1. Kernel fusion - reduces global memory accesses
# 2. Each thread block handles one row (batch element)
# 3. Warp-level reductions for softmax computation

fused_matmul_dropout_softmax_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

// XOR-shift random number generator - deterministic and fast
__device__ unsigned int xorshift(unsigned int x) {
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

// Fused kernel for: linear (matmul+bias) + dropout + softmax
__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    unsigned int seed)
{
    // Each thread block handles one batch element
    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) return;

    // Each thread in the block handles one output feature
    int thread_idx = threadIdx.x;
    int out_features_for_thread = (out_features + blockDim.x - 1) / blockDim.x;

    int out_start = thread_idx * out_features_for_thread;
    int out_end = min(out_start + out_features_for_thread, out_features);

    // Shared memory for thread-level max and sum
    __shared__ float s_max[1024];
    __shared__ float s_sum[1024];

    // First compute matmul for this thread's portion of output
    float local_max = -INFINITY;

    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        // Bias
        float val = bias[out_idx];

        // Dot product
        const float* weight_row = &weight[out_idx * in_features];
        const float* input_row = &input[batch_idx * in_features];

        // Unroll loop for better performance
        for (int i = 0; i < in_features; i++) {
            val += weight_row[i] * input_row[i];
        }

        // Apply dropout (scaled)
        unsigned int rand_state = seed + batch_idx * out_features + out_idx + thread_idx;
        float rand_val = (float)(xorshift(rand_state)) / (float)UINT_MAX;
        if (rand_val < dropout_p) {
            val = 0.0f;
        } else {
            val = val / (1.0f - dropout_p);
        }

        // Store temporary value for softmax
        output[batch_idx * out_features + out_idx] = val;

        // Track max
        local_max = fmaxf(local_max, val);
    }

    s_max[thread_idx] = local_max;
    __syncthreads();

    // Reduction to get row maximum
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (thread_idx < stride) {
            s_max[thread_idx] = fmaxf(s_max[thread_idx], s_max[thread_idx + stride]);
        }
        __syncthreads();
    }

    float row_max = s_max[0];
    __syncthreads();

    // Compute exp((x - max)) and sum
    float local_sum = 0.0f;
    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        float val = output[batch_idx * out_features + out_idx];
        float exp_val = expf(val - row_max);
        output[batch_idx * out_features + out_idx] = exp_val;
        local_sum += exp_val;
    }

    s_sum[thread_idx] = local_sum;
    __syncthreads();

    // Reduction to get row sum
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (thread_idx < stride) {
            s_sum[thread_idx] += s_sum[thread_idx + stride];
        }
        __syncthreads();
    }

