#include <hip/hip_runtime.h>

__global__ void matmul_divide_gelu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int input_size,
    int output_size,
    float divisor
) {
    int row = blockIdx.x * blockDim.y + threadIdx.y;
    int col = blockIdx.y * blockDim.x + threadIdx.x;

    if (row >= batch_size || col >= output_size) {
        return;
    }

    float sum = 0.0f;

    #pragma unroll 4
    for (int k = 0; k < input_size; k++) {
        sum += input[row * input_size + k] * weight[k * output_size + col];
    }

    sum = sum / divisor;

    float x = sum;
    float x_cube = x * x * x;
    float tanh_arg = 0.7978845608028654f * (x + 0.044715f * x_cube);
    float gelu_val = 0.5f * x * (1.0f + tanhf(tanh_arg));

    output[row * output_size + col] = gelu_val;
}

