    int d_out = (depth + 3) / 4;
    int h_out = (height + 3) / 4;
    int w_out = (width + 3) / 4;

    auto output = torch::zeros({channels, d_out, h_out, w_out}, input.options());

    dim3 blocks(d_out, h_out, w_out);
    dim3 threads(channels > 256 ? 256 : channels);

    if (channels <= 256) {
