        for (int n = 0; n < TILE; n++) {
            sum += As[threadIdx.y][n] * Bs[n][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < batch_size && col < output_size) {
        sum = sum / divisor;
        float x = sum;
        float x_cube = x * x * x;
        float tanh_arg = 0.7978845608028654f * (x + 0.044715f * x_cube);
