        float sum = 0.0f;

        for (int k = 0; k < K; k++) {
            sum += input[row * K + k] * weight[col * K + k];
        }

        float swish_val = sum * sigmoid_hip(sum);

        output[row * N + col] = swish_val * scaling_factor;
    }
}

