# Matrix multiplication with shared memory tiling
matmul_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    const int TILE_SIZE = 16;
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles
        if (row < M && threadIdx.x + t * TILE_SIZE < K) {
            As[threadIdx.y][threadIdx.x] = A[row * K + threadIdx.x + t * TILE_SIZE];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (col < N && threadIdx.y + t * TILE_SIZE < K) {
            Bs[threadIdx.y][threadIdx.x] = B[(threadIdx.y + t * TILE_SIZE) * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sums
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; ++i) {
            sum += As[threadIdx.y][i] * Bs[i][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B, int out_features) {
    auto M = A.size(0);  // batch_size * in_features
    auto N = out_features;
    auto K = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    matmul_kernel<<<grid, block>>>(
        reinterpret_cast<const float*>(A.data_ptr<float>()),
        reinterpret_cast<const float*>(B.data_ptr<float>()),
        reinterpret_cast<float*>(C.data_ptr<float>()),
        M, N, K
    );

    return C;
}
"""

# Fused GELU + Scale kernel
gelu_scale_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gelu_scale_kernel(const float* x, float* out, int size, float scale) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // GELU approximation: x * 0.5 * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        float cube = val * val * val;
        float tanh_arg = 0.7978845608028654f * (val + 0.044715f * cube);
        float gelu_val = val * 0.5f * (1.0f + tanhf(tanh_arg));
        out[idx] = gelu_val * scale;
    }
}

torch::Tensor gelu_scale_hip(torch::Tensor x, float scale) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_scale_kernel<<<num_blocks, block_size>>>(
        reinterpret_cast<const float*>(x.data_ptr<float>()),
        reinterpret_cast<float*>(out.data_ptr<float>()),
        size,
        scale
    );

    return out;
}
"""

# Parallel max reduction kernel
max_reduce_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void max_reduce_kernel(const float* x, float* out, int batch_size, int num_features) {
    int batch_idx = blockIdx.x;

    __shared__ float shared_max[256];

    int local_idx = threadIdx.x;
    int global_idx = batch_idx * num_features + local_idx;

    // Load values into shared memory
    float max_val = -FLT_MAX;
    for (int i = local_idx; i < num_features; i += blockDim.x) {
        int idx = batch_idx * num_features + i;
        if (idx < batch_size * num_features) {
            max_val = fmaxf(max_val, x[idx]);
        }
    }
    shared_max[local_idx] = max_val;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (local_idx < s) {
            shared_max[local_idx] = fmaxf(shared_max[local_idx], shared_max[local_idx + s]);
        }
        __syncthreads();
    }

    // Write result
    if (local_idx == 0) {
        out[batch_idx] = shared_max[0];
    }
}

torch::Tensor max_reduce_hip(torch::Tensor x) {
    int batch_size = x.size(0);
    int num_features = x.size(1);

    auto out = torch::zeros({batch_size}, x.options());

    const int block_size = 256;
    const int num_blocks = batch_size;

    max_reduce_kernel<<<num_blocks, block_size>>>(
        reinterpret_cast<const float*>(x.data_ptr<float>()),
        reinterpret_cast<float*>(out.data_ptr<float>()),
        batch_size,
        num_features
    );

    return out;
}
"""

