from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

conv_instnorm_divide_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void conv_instnorm_divide_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    int kernel_size,
    float divide_by,
    float eps) {

    // Output pixel position
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int batch_idx = blockIdx.z;
    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int block_tid = tid;

    // Use reduced shared memory for mean/variance accumulation
    extern __shared__ float shared_stats[];

    // Compute total pixels for output
    int out_num_pixels = out_height * out_width;
    bool is_valid_pixel = (x < out_width && y < out_height);

    for (int out_c = 0; out_c < out_channels; out_c++) {
        // Initialize shared memory for this channel
        shared_stats[tid] = 0.0f;
        shared_stats[tid + blockDim.x * blockDim.y] = 0.0f;
        __syncthreads();

        // Compute convolution output for this pixel and channel
        float conv_out = 0.0f;

        if (bias != nullptr) {
            conv_out = bias[out_c];
        }

        // Convolution computation (without padding)
        for (int in_c = 0; in_c < in_channels; in_c++) {
            for (int ky = 0; ky < kernel_size; ky++) {
                for (int kx = 0; kx < kernel_size; kx++) {
                    int in_y = y + ky;
                    int in_x = x + kx;

                    if (in_y >= 0 && in_y < in_height && in_x >= 0 && in_x < in_width) {
                        int in_idx = ((batch_idx * in_channels + in_c) * in_height + in_y) * in_width + in_x;
                        int w_idx = ((out_c * in_channels + in_c) * kernel_size + ky) * kernel_size + kx;
                        conv_out += input[in_idx] * weight[w_idx];
                    }
                }
            }
        }

        // Accumulate for mean and variance
        float local_sum = is_valid_pixel ? conv_out : 0.0f;
        float local_sq_sum = is_valid_pixel ? conv_out * conv_out : 0.0f;

        atomicAdd(&shared_stats[tid], local_sum);
        atomicAdd(&shared_stats[tid + blockDim.x * blockDim.y], local_sq_sum);
        __syncthreads();

        // Block reduction to get total sum and sq_sum
        if (block_tid < 64) {
            for (int i = block_tid + 64; i < blockDim.x * blockDim.y; i += 64) {
                shared_stats[block_tid] += shared_stats[i];
                shared_stats[block_tid + blockDim.x * blockDim.y] += shared_stats[i + blockDim.x * blockDim.y];
            }
        }
        __syncthreads();

        if (block_tid == 0) {
            // Total sum and sq_sum are in the first element
            float total_sum = shared_stats[0];
            float total_sq_sum = shared_stats[blockDim.x * blockDim.y];

            // Compute mean and variance
            float mean = total_sum / out_num_pixels;
            float variance = total_sq_sum / out_num_pixels - mean * mean;
            variance = fmaxf(variance, 0.0f);

            // Store mean and std for this channel
            shared_stats[0] = mean;
            shared_stats[1] = sqrtf(variance + eps);
        }
        __syncthreads();

        // Normalize the output and write
        if (is_valid_pixel) {
            float mean = shared_stats[0];
            float std = shared_stats[1];
            float norm_val = (conv_out - mean) / std;
            norm_val = norm_val / divide_by;

            int out_idx = ((batch_idx * out_channels + out_c) * out_height + y) * out_width + x;
            output[out_idx] = norm_val;
        }
        __syncthreads();
    }
}

torch::Tensor conv_instnorm_divide_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float divide_by) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_height = input.size(2);
    int in_width = input.size(3);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    // Compute output size for conv2d with no padding
    int out_height = in_height - kernel_size + 1;
    int out_width = in_width - kernel_size + 1;

    float eps = 1e-5f;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    const int threads_x = 16;
    const int threads_y = 16;
    int num_blocks_x = (out_width + threads_x - 1) / threads_x;
    int num_blocks_y = (out_height + threads_y - 1) / threads_y;

    // Reduced shared memory: only need space for reduction
    int block_threads = threads_x * threads_y;
    int shared_mem_size = (2 * block_threads) * sizeof(float);

    dim3 blocks(num_blocks_x, num_blocks_y, batch_size);
    dim3 threads(threads_x, threads_y);

    conv_instnorm_divide_kernel<<<blocks, threads, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_height,
        in_width,
        out_height,
        out_width,
        kernel_size,
        divide_by,
        eps);

    return output;
}
