class ModelNew(nn.Module):
    """
    Optimized model with fused Swish + Bias + GroupNorm kernel
    """
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()

        # Linear transformation (matrix multiplication)
        # Initialize same as reference: nn.Linear has weight[out_features, in_features]
        self.linear_weight = nn.Parameter(torch.randn(out_features, in_features))
        self.linear_bias = nn.Parameter(torch.randn(out_features)) if bias_shape == (out_features,) else nn.Parameter(torch.randn(bias_shape))

        # GroupNorm parameters
        self.weight = nn.Parameter(torch.ones(out_features))  # gamma
        self.bias_gn = nn.Parameter(torch.zeros(out_features))  # beta
        self.num_groups = num_groups

        # Fused kernel
        self.fused_kernel = fused_swish_bias_groupnorm

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).
        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_features).
