        # Matrix multiplication
        x = torch.matmul(x, self.linear_weight.t())

        # Fused: Swish + bias addition + GroupNorm
        # Note: The bias added after Swish is self.linear_bias
        x = self.fused_kernel.fused_swish_bias_groupnorm_hip(
            x, 
            self.weight, 
            self.bias_gn, 
            self.linear_bias, 
            self.num_groups
        )

        return x

