# Fused kernel: linear (matmul+bias) + dropout + softmax
# Optimizations:
# 1. Kernel fusion - reduces global memory accesses
# 2. Each thread block handles one batch element
# 3. Parallel computation across output features
# 4. Efficient softmax with two-pass algorithm

fused_matmul_dropout_softmax_source = """
#include <hip/hip_runtime.h>

__device__ float fast_exp(float x) {
    // Fast approximate exponential using Taylor series
    // Good enough for softmax numerical stability
    union { unsigned int i; float f; } u;
    u.i = (int)(12102203.0f * x) + 127 * (1 << 23);
    int m = (u.i >> 23) & 255;
    if (m < 255) {
        u.i = (12102203 * (int)(x - (int)x + (m - 127)));
    }
    return u.f;
}

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    unsigned int seed)
{
    // Each block processes one batch element
    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int total_threads = blockDim.x;

    // Partition output features among threads
    int out_start = (out_features * tid) / total_threads;
    int out_end = (out_features * (tid + 1)) / total_threads;

    // Shared memory for softmax computation
    __shared__ float s_max[1024];
    __shared__ float s_sum[1024];

    // Phase 1: Compute matmul + dropout and find row-wise maximum
    float local_max = -1e38f;

    const float* input_ptr = &input[batch_idx * in_features];

    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        // Start with bias
        float val = bias[out_idx];

        // Dot product with vectorized approach
        const float* weight_row = &weight[out_idx * in_features];

        // Manual loop for max performance
        for (int i = 0; i < in_features; i++) {
            val += weight_row[i] * input_ptr[i];
        }

        // Apply dropout with deterministic hashing
        unsigned int hash = seed;
        hash ^= (unsigned int)(batch_idx * 2654435761);
        hash ^= (unsigned int)(out_idx * 2654435761);

        float rand_val = (float)(hash) / (float)(0xFFFFFFFFu);

        if (rand_val < dropout_p) {
            val = 0.0f;
        } else {
            val = val / (1.0f - dropout_p);
        }

        // Store intermediate result
        output[batch_idx * out_features + out_idx] = val;

        // Track maximum for softmax
        local_max = fmaxf(local_max, val);
    }

    s_max[tid] = local_max;
    __syncthreads();

    // Reduction: find maximum across all threads
    for (int stride = total_threads / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_max[tid] = fmaxf(s_max[tid], s_max[tid + stride]);
        }
        __syncthreads();
    }

    float row_max = s_max[0] + 1e-38f;  // Avoid division by zero
    __syncthreads();

    // Phase 2: Compute exponentials and sum
    float local_sum = 0.0f;

    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        float val = output[batch_idx * out_features + out_idx];
        float exp_val = __expf(val - row_max);
        output[batch_idx * out_features + out_idx] = exp_val;
        local_sum += exp_val;
    }

    s_sum[tid] = local_sum;
    __syncthreads();

    // Reduction: sum across all threads
    for (int stride = total_threads / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
        }
        __syncthreads();
    }

    float row_sum = s_sum[0] + 1e-38f;  // Avoid division by zero

    // Phase 3: Normalize
    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        output[batch_idx * out_features + out_idx] = 
            output[batch_idx * out_features + out_idx] / row_sum;
    }
}

