    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void conv_instnorm_divide_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    int kernel_size,
    float divide_by,
    float eps) {

    // Output pixel position
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int batch_idx = blockIdx.z;
    bool is_valid_pixel = (x < out_width && y < out_height);

    // Compute total pixels for output
    int out_num_pixels = out_height * out_width;

    // Process each output channel
    for (int out_c = 0; out_c < out_channels; out_c++) {
        // Compute convolution output for this pixel and channel
        float conv_out = 0.0f;

        if (bias != nullptr) {
            conv_out = bias[out_c];
        }

        if (is_valid_pixel) {
            // Convolution computation (without padding)
            for (int in_c = 0; in_c < in_channels; in_c++) {
                for (int ky = 0; ky < kernel_size; ky++) {
                    for (int kx = 0; kx < kernel_size; kx++) {
                        int in_y = y + ky;
                        int in_x = x + kx;

                        if (in_y >= 0 && in_y < in_height && in_x >= 0 && in_x < in_width) {
                            int in_idx = ((batch_idx * in_channels + in_c) * in_height + in_y) * in_width + in_x;
                            int w_idx = ((out_c * in_channels + in_c) * kernel_size + ky) * kernel_size + kx;
                            conv_out += input[in_idx] * weight[w_idx];
                        }
                    }
                }
            }
        }

        // Compute sum and sq_sum for statistics (first pass)
        float local_sum = is_valid_pixel ? conv_out : 0.0f;
        float local_sq_sum = is_valid_pixel ? conv_out * conv_out : 0.0f;

        // Warp reduction
        float warp_sum = warp_reduce_sum(local_sum);
        float warp_sq_sum = warp_reduce_sum(local_sq_sum);

        // Find the first active lane in each warp to accumulate
        int lane_id = threadIdx.x % 32;
        int warp_id = threadIdx.x / 32 + (threadIdx.y * blockDim.x) / 32;

        // Use float atomic in global memory for accumulation
        __shared__ float gSum[32];
        __shared__ float gSqSum[32];

        if (lane_id == 0) {
            gSum[warp_id % 32] = warp_sum;
            gSqSum[warp_id % 32] = warp_sq_sum;
        }
        __syncthreads();

        float block_sum = 0.0f;
        float block_sq_sum = 0.0f;

        if (lane_id < min(32, (blockDim.x * blockDim.y + 31) / 32)) {
            block_sum = gSum[lane_id];
            block_sq_sum = gSqSum[lane_id];
        }

        block_sum = warp_reduce_sum(block_sum);
        block_sq_sum = warp_reduce_sum(block_sq_sum);

        // Compute mean and std
        float mean = (lane_id == 0) ? block_sum / out_num_pixels : 0.0f;
        float std = (lane_id == 0) ? sqrtf(fmaxf(block_sq_sum / out_num_pixels - mean * mean, 0.0f) + eps) : 0.0f;

        // Broadcast to all threads
        mean = __shfl(mean, 0);
        std = __shfl(std, 0);

        // Normalize the output and write
        if (is_valid_pixel) {
            float norm_val = (conv_out - mean) / std;
            norm_val = norm_val / divide_by;

            int out_idx = ((batch_idx * out_channels + out_c) * out_height + y) * out_width + x;
            output[out_idx] = norm_val;
        }
    }
}

