#include <hip/hip_runtime.h>

__global__ void fused_matmul_dropout_softmax_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features,
    float dropout_p,
    unsigned int seed)
{
    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int total_threads = blockDim.x;

    // Range of output features for this thread
    int out_start = (out_features * tid) / total_threads;
    int out_end = (out_features * (tid + 1)) / total_threads;

    // Shared memory for max and sum
    extern __shared__ float shared_mem[];
    float* s_max = &shared_mem[0];
    float* s_sum = &shared_mem[blockDim.x];

    const float* input_ptr = &input[batch_idx * in_features];

    // Pass 1: Compute weighted sum + dropout, find max
    float local_max = -1e20f;

    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        float val = bias[out_idx];

        // Matmul
        const float* weight_ptr = &weight[out_idx * in_features];
        for (int i = 0; i < in_features; i++) {
            val += weight_ptr[i] * input_ptr[i];
        }

        // Dropout
        unsigned int h = seed + (unsigned int)(batch_idx * out_features + out_idx);
        float rand_val = (float)(h) / (float)(0xFFFFFFFFu);
        if (rand_val < dropout_p) {
            val = 0.0f;
        } else {
            val = val / (1.0f - dropout_p);
        }

        output[batch_idx * out_features + out_idx] = val;
        local_max = fmaxf(local_max, val);
    }

    s_max[tid] = local_max;
    __syncthreads();

    // Reduce max
    for (int s = total_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_max[tid] = fmaxf(s_max[tid], s_max[tid + s]);
        }
        __syncthreads();
    }

    float row_max = s_max[0];
    __syncthreads();

    // Pass 2: Compute exp and sum
    float local_sum = 0.0f;
    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        float val = output[batch_idx * out_features + out_idx] - row_max;
        float exp_val = expf(val);
        output[batch_idx * out_features + out_idx] = exp_val;
        local_sum += exp_val;
    }

    s_sum[tid] = local_sum;
    __syncthreads();

    // Reduce sum
    for (int s = total_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
        }
        __syncthreads();
    }

    float row_sum = s_sum[0] + 1e-20f;

    // Pass 3: Normalize
    for (int out_idx = out_start; out_idx < out_end; out_idx++) {
        output[batch_idx * out_features + out_idx] = 
            output[batch_idx * out_features + out_idx] / row_sum;
    }
}

