#include <hip/hip_runtime.h>
#include <math.h>

__device__ __forceinline__ float softplus(float x) {
    // log(1 + exp(x)) with numerical stability
    if (x > 15.0f) {
        return x + logf(1.0f + expf(-x));
    } else if (x < -15.0f) {
        return expf(x);
    } else {
        return logf(1.0f + expf(x));
    }
}

__global__ void fused_activation_bnorm_kernel(
    const float* input,
    const float* running_mean,
    const float* running_var,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int channels,
    int height,
    int width,
    float eps) {

    // Use 2D block layout for better spatial locality
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // width
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // height
    int channel = blockIdx.z;  // channels
    int batch = blockIdx.z / channels;  // batch

    // Note: need to fix channel/batch indexing
    int linear_block = blockIdx.z;
    batch = linear_block / channels;
    int actual_channel = linear_block % channels;

    // Check bounds
    if (col >= width || row >= height) return;

    // Compute linear index
    int idx = batch * channels * height * width + actual_channel * height * width + row * width + col;

    // Load input value
    float x = input[idx];

    // Compute fused activation: x * tanh(softplus(x))
    float sp = softplus(x);
    float tanh_sp = tanhf(sp);
    float activated = x * tanh_sp;

    // Load BatchNorm parameters for this channel
    float mean = running_mean[actual_channel];
    float var = running_var[actual_channel];
    float gamma = weight[actual_channel];
    float beta = bias[actual_channel];

    // Compute BatchNorm
    float norm = sqrtf(var + eps);
    float output_val = (activated - mean) / norm * gamma + beta;

    // Write result
    output[idx] = output_val;
}

