    int bx = blockIdx.x;
    if (bx >= bs) return;

    int tx = threadIdx.x;
    int n = blockDim.x;

    int start = (outf * tx) / n;
    int end = (outf * (tx + 1)) / n;

    __shared__ float sm[1024];

    // Pass 1: matmul + dropout, find max
    float mx = -1e30;
    const float* ip = in + bx * inf;

    for (int j = start; j < end; j++) {
        float sum = b[j];
        const float* wp = w + j * inf;
        for (int i = 0; i < inf; i++) sum += wp[i] * ip[i];

        unsigned int h = seed + (unsigned int)(bx * outf + j);
        float r = (float)h / (float)0xffffffffu;
        if (r < dp) sum = 0.0f; else sum /= (1.0f - dp);

        out[bx * outf + j] = sum;
        mx = fmaxf(mx, sum);
    }

    sm[tx] = mx;
    __syncthreads();
    for (int s = n/2; s; s>>=1) {
        if (tx < s) sm[tx] = fmaxf(sm[tx], sm[tx+s]);
        __syncthreads();
    }
    mx = sm[0];

    // Pass 2: exp and sum
    float tot = 0.0f;
    for (int j = start; j < end; j++) {
        float v = expf(out[bx * outf + j] - mx);
        out[bx * outf + j] = v;
        tot += v;
    }

    sm[tx] = tot;
    __syncthreads();
    for (int s = n/2; s; s>>=1) {
        if (tx < s) sm[tx] += sm[tx+s];
        __syncthreads();
    }
    tot = sm[0];

    // Pass 3: normalize
    for (int j = start; j < end; j++) {
        out[bx * outf + j] /= tot;
    }
}

