    const float* scale,
    float* output,
    int batch_size,
    int channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    int pool_size,
    float clamp_min,
    float clamp_max) {

    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;

    // Output position
    int out_h = threadIdx.y + blockIdx.x * blockDim.y;
    int out_w = threadIdx.x + blockIdx.y * blockDim.x;

    // Adjust block indexing for 2D grid
    int block_h = blockIdx.x;
    int block_w = blockIdx.y;

    out_h = threadIdx.y + block_h * blockDim.y;
    out_w = threadIdx.x + block_w * blockDim.x;

    // Calculate pooling window start in input
    int in_h_start = out_h * pool_size;
    int in_w_start = out_w * pool_size;

    // Check if this thread is responsible for a valid output position
    if (out_h < height_out && out_w < width_out && batch_idx < batch_size && channel_idx < channels) {

        // Get scale value for this channel
        float scale_val = scale[channel_idx];

        // Compute max pooling across the window
        float max_val = -1e30f;

        for (int ph = 0; ph < pool_size; ph++) {
            for (int pw = 0; pw < pool_size; pw++) {
                int in_h = in_h_start + ph;
                int in_w = in_w_start + pw;

                if (in_h < height_in && in_w < width_in) {
                    int in_idx = batch_idx * channels * height_in * width_in +
                                 channel_idx * height_in * width_in +
                                 in_h * width_in + in_w;

                    float val = input[in_idx] * scale_val;
                    max_val = max(max_val, val);
                }
            }
        }

        // Clamp the result
        max_val = max(clamp_min, min(clamp_max, max_val));

        // Write output
        int out_idx = batch_idx * channels * height_out * width_out +
                      channel_idx * height_out * width_out +
                      out_h * width_out + out_w;
        output[out_idx] = max_val;
    }
}

