class ModelNew(nn.Module):
    """
    Optimized model with custom HIP kernels
    """
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.pool_kernel_size = pool_kernel_size
        self.scale_factor = scale_factor
        self.avg_pool = nn.AvgPool1d(kernel_size=pool_kernel_size)
        self.register_buffer('weight', torch.randn(out_features, in_features))

    def forward(self, x):
        batch_size = x.size(0)
        x = kernels.matmul_hip(x.view(-1, self.in_features), self.weight.T, self.out_features)
        x = x.view(batch_size, self.out_features)
        x = self.avg_pool(x.unsqueeze(1)).squeeze(1)
        x = kernels.gelu_scale_hip(x, self.scale_factor)
        x = kernels.max_reduce_hip(x)
        return x

