    int out_features) {

    int batch_idx = blockIdx.x;
    int out_idx = threadIdx.x;

    if (out_idx >= out_features) return;

    __shared__ float input_tile[TILE_SIZE];
    __shared__ float weight_tile[TILE_SIZE];

    // Start with bias
    float sum = bias[out_idx];

    // Tiled matmul
    for (int tile_start = 0; tile_start < in_features; tile_start += TILE_SIZE) {
        // Load input tile (broadcast this row to all threads in block)
        int tile_end = min(tile_start + TILE_SIZE, in_features);
        int tile_size = tile_end - tile_start;

        if (out_idx < tile_size) {
            input_tile[out_idx] = input[batch_idx * in_features + tile_start + out_idx];
            // Only first thread needs to load weight row
            if (batch_idx == 0 || true) {
                weight_tile[out_idx] = weight[out_idx * in_features + tile_start + out_idx];
            }
        }
        __syncthreads();

        // Compute partial dot product
        if (out_idx < out_features) {
            for (int i = 0; i < tile_size; i++) {
                sum += input_tile[i] * weight_tile[i];
            }
        }
        __syncthreads();
    }

    // Apply GELU
    float x = sum;
    float gelu_val = x * 0.5f * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));

    // Softmax across features using shared memory
    __shared__ float smem[256];
    int tid = out_idx;

    smem[tid] = (tid < out_features) ? gelu_val : 0.0f;
    __syncthreads();

    // Find max for numerical stability
    float max_val = -INFINITY;
    for (int s = 128; s > 0; s >>= 1) {
        if (tid < s && (tid + s) < out_features) {
            smem[tid] = fmaxf(smem[tid], smem[tid + s]);
        }
        __syncthreads();
    }
    __syncthreads();
    max_val = smem[0];
    __syncthreads();

    // Compute exp and sum
    float exp_val = (tid < out_features) ? expf(gelu_val - max_val) : 0.0f;

    smem[tid] = exp_val;
    __syncthreads();

    // Reduction for sum
    for (int s = 128; s > 0; s >>= 1) {
        if (tid < s && (tid + s) < out_features) {
            smem[tid] += smem[tid + s];
        }
        __syncthreads();
    }
    __syncthreads();

    float sum_exp = smem[0];

    // Output
    int global_idx = batch_idx * out_features + out_idx;
    if (tid < out_features) {
        output[global_idx] = exp_val / sum_exp;
    }
}
