#include <hip/hip_runtime.h>

__global__ void scale_maxpool_clamp_kernel(
    const float* input,
    const float* scale,
    float* output,
    int batch_size,
    int channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out,
    int pool_size,
    float clamp_min,
    float clamp_max) {

    // 3D grid: z=batch, y=channel, x=spatial (linearized)
    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;

    // Linear spatial index
    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Convert to h,w coordinates
    int out_h = spatial_idx / width_out;
    int out_w = spatial_idx % width_out;

    // Check bounds
    if (out_h < height_out && out_w < width_out && batch_idx < batch_size && channel_idx < channels) {

        // Get scale value for this channel
        float scale_val = scale[channel_idx];

        // Calculate pooling window start in input
        int in_h_start = out_h * pool_size;
        int in_w_start = out_w * pool_size;

        // Compute max pooling across the window
        float max_val = -1e30f;

        for (int ph = 0; ph < pool_size; ph++) {
            for (int pw = 0; pw < pool_size; pw++) {
                int in_h = in_h_start + ph;
                int in_w = in_w_start + pw;

                if (in_h < height_in && in_w < width_in) {
                    int in_idx = batch_idx * channels * height_in * width_in +
                                 channel_idx * height_in * width_in +
                                 in_h * width_in + in_w;

                    float val = input[in_idx] * scale_val;
                    max_val = max(max_val, val);
                }
            }
        }

        // Clamp the result
        max_val = max(clamp_min, min(clamp_max, max_val));

        // Write output
        int out_idx = batch_idx * channels * height_out * width_out +
                      channel_idx * height_out * width_out +
                      out_h * width_out + out_w;
        output[out_idx] = max_val;
    }
}

torch::Tensor scale_maxpool_clamp_hip(
    torch::Tensor input,
    torch::Tensor scale,
    int pool_size,
    float clamp_min,
    float clamp_max) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height_in = input.size(2);
    auto width_in = input.size(3);

    auto height_out = height_in / pool_size;
    auto width_out = width_in / pool_size;
    int spatial_size_out = height_out * width_out;

    auto output = torch::zeros({batch_size, channels, height_out, width_out}, input.options());

    const int block_size = 256;
    int grid_size = (spatial_size_out + block_size - 1) / block_size;

    dim3 grid_dim(grid_size, channels, batch_size);

    scale_maxpool_clamp_kernel<<<grid_dim, block_size>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height_in,
        width_in,
        height_out,
        width_out,
        pool_size,
        clamp_min,
        clamp_max);

    return output;
}
