fused_activation_norm_cpp_source = """
#include <hip/hip_runtime.h>

__constant__ float eps = 1e-5f;

__global__ void fused_swish_bias_groupnorm_kernel(
    const float* x,
    const float* weight,  // GroupNorm gamma
    const float* bias_gn, // GroupNorm beta
    const float* bias_add, // Bias to add before GroupNorm
    float* out,
    int batch_size,
    int num_features,
    int num_groups
) {
    int batch_idx = blockIdx.x;
    int thread_idx = threadIdx.x;
    int total_threads = blockDim.x;

    int features_per_group = num_features / num_groups;

    // Shared memory for reduction (2 * num_groups)
    extern __shared__ float shared_data[];
    float* s_sum = shared_data;
    float* s_sq_sum = &shared_data[num_groups];

    // Initialize shared memory
    if (thread_idx < num_groups) {
        s_sum[thread_idx] = 0.0f;
        s_sq_sum[thread_idx] = 0.0f;
    }
    __syncthreads();

    // First pass: compute swish, add bias, accumulate statistics
    for (int elem = thread_idx; elem < num_features; elem += total_threads) {
        int group_idx = elem / features_per_group;
        int idx = batch_idx * num_features + elem;

        // Read input from matmul output
        float val = x[idx];

        // Apply Swish activation: sigmoid(x) * x
        float sigmoid_val = 1.0f / (1.0f + expf(-val));
        float swish_val = sigmoid_val * val;

        // Add external bias (from nn.Parameter)
        float b_val = (bias_add != nullptr) ? bias_add[elem] : 0.0f;
        val = swish_val + b_val;

        // Accumulate sums for GroupNorm
        atomicAdd(&s_sum[group_idx], val);
        atomicAdd(&s_sq_sum[group_idx], val * val);
    }

    __syncthreads();

    // Compute mean and variance for each group (using shared memory)
    __shared__ float mean[64];
    __shared__ float inv_std[64];

    if (thread_idx < num_groups) {
        mean[thread_idx] = s_sum[thread_idx] / features_per_group;
        float variance = s_sq_sum[thread_idx] / features_per_group - mean[thread_idx] * mean[thread_idx];
        inv_std[thread_idx] = rsqrtf(variance + eps);
    }

    __syncthreads();

    // Second pass: normalize and apply GroupNorm weight/bias
    for (int elem = thread_idx; elem < num_features; elem += total_threads) {
        int group_idx = elem / features_per_group;
        int idx = batch_idx * num_features + elem;

        // Read input again and compute full pipeline
        float val = x[idx];

        // Swish
        float sigmoid_val = 1.0f / (1.0f + expf(-val));
        float swish_val = sigmoid_val * val;

        // Add bias
        float b_val = (bias_add != nullptr) ? bias_add[elem] : 0.0f;
        val = swish_val + b_val;

        // GroupNorm: apply normalization and affine transform
        float group_mean = mean[group_idx];
        float group_inv_std = inv_std[group_idx];

        // Normalize: (x - mean) / std
        val = (val - group_mean) * group_inv_std;

        // Apply affine transform: weight * x + bias
        if (weight != nullptr) {
            val = val * weight[elem];
        }
        if (bias_gn != nullptr) {
            val = val + bias_gn[elem];
        }

        out[idx] = val;
    }
}

torch::Tensor fused_swish_bias_groupnorm_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias_gn,
    torch::Tensor bias_add,
    int num_groups
) {
    auto batch_size = x.size(0);
    auto num_features = x.size(1);

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = batch_size;

    size_t shared_mem_size = 2 * num_groups * sizeof(float);

    fused_swish_bias_groupnorm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_gn.data_ptr<float>(),
        bias_add.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        num_features,
        num_groups
    );

    return out;
}
