activation_bnorm_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>

__device__ __forceinline__ float softplus(float x) {
    // log(1 + exp(x)) with numerical stability
    if (x > 15.0f) {
        return x + logf(1.0f + expf(-x));
    } else if (x < -15.0f) {
        return expf(x);
    } else {
        return logf(1.0f + expf(x));
    }
}

__global__ void fused_activation_bnorm_kernel_vec4(
    const float* __restrict__ input,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height,
    int width,
    float eps) {

    // Process 4 elements per thread for better memory throughput
    int base_idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    int total_elements = batch_size * channels * height * width;

    if (base_idx >= total_elements) return;

    // Load mean, var, gamma, beta for this channel (cached in registers)
    // Convert linear index to channel
    int elements_per_channel = height * width;
    int idx_cpy = base_idx;
    int batch = idx_cpy / (channels * elements_per_channel);
    idx_cpy = idx_cpy % (channels * elements_per_channel);
    int channel = idx_cpy / elements_per_channel;

    float mean = running_mean[channel];
    float var = running_var[channel];
    float gamma = weight[channel];
    float beta = bias[channel];

    // Pre-compute BatchNorm scale and shift
    float norm = sqrtf(var + eps);
    float scale = gamma / norm;
    float shift = beta - mean * scale;

    // Process 4 elements
    float4 x4 = reinterpret_cast<const float4*>(input)[base_idx / 4];

    // Compute activation + batchnorm for each element
    float x0 = x4.x;
    float sp0 = softplus(x0);
