    float out1 = x1 * tanhf(sp1) * scale + shift;

    float x2 = x4.z;
    float sp2 = softplus(x2);
    float out2 = x2 * tanhf(sp2) * scale + shift;

    float x3 = x4.w;
    float sp3 = softplus(x3);
    float out3 = x3 * tanhf(sp3) * scale + shift;

    // Write results
    float4 out4;
    out4.x = out0;
    out4.y = out1;
    out4.z = out2;
    out4.w = out3;

    reinterpret_cast<float4*>(output)[base_idx / 4] = out4;
