    int height,
    int width,
    float eps,
    int start_idx,
    int num_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x + start_idx;

    if (idx >= num_elements) return;

    // Convert linear index to (batch, channel, height, width)
    int elements_per_channel = height * width;
