    int remainder = idx % (channels * elements_per_channel);
    int channel = remainder / elements_per_channel;
    int hw_idx = remainder % elements_per_channel;

    // Load input value
    float x = input[idx];

    // Compute fused activation: x * tanh(softplus(x))
    float sp = softplus(x);
    float activated = x * tanhf(sp);

    // Load BatchNorm parameters for this channel
    float mean = running_mean[channel];
    float var = running_var[channel];
    float gamma = weight[channel];
    float beta = bias[channel];

    // Compute BatchNorm with pre-computed values
    float norm = sqrtf(var + eps);
    float output_val = (activated - mean) / norm * gamma + beta;

    // Write result
    output[idx] = output_val;
