    int height_out,
    int width_out,
    int pool_size,
    float clamp_min,
    float clamp_max) {

    int batch_idx = blockIdx.z;
    int channel_idx = blockIdx.y;

    // 2D output position
    int out_h_base = (blockIdx.x / ((width_out + 15) / 16)) * 16;
    int out_w_base = (blockIdx.x % ((width_out + 15) / 16)) * 16;

    int out_h = out_h_base + threadIdx.y;
    int out_w = out_w_base + threadIdx.x;

